function resolveGlyph(name = '') {
  const raw = String(name || '').toLowerCase();
  if (!raw) return '•';
  const compact = raw.replace(/-outline|-sharp|-circle|-half|-off|-small|-large|-multiple|-box|-variant|-alert|-clock|-edit|-file|-minus|-plus|-remove|-search|-text|-check|-play|-pulse|-off|-play-outline|-search-outline|-off-outline|-outline$/g, '');
  if (MAP[raw]) return MAP[raw];
  if (MAP[compact]) return MAP[compact];
  const foundKey = Object.keys(MAP).find((key) => compact.includes(key));
  if (foundKey) return MAP[foundKey];
  return '•';
}

function MaterialCommunityIcons(props) {
  const glyph = resolveGlyph(props?.name);
  const size = Number(props?.size || 16);
  const color = props?.color || '#0f172a';
  return React.createElement(Text, { style: [{ fontSize: size, color }, props?.style] }, glyph);
}

module.exports = MaterialCommunityIcons;
module.exports.default = MaterialCommunityIcons;
